# Origin: the climb's outside judges, fourth wave (proposed decisions addendum 16; notebook docs/drills/field/out_o11.md).
# A fresh agent with no repo access, playing a prepared top team (embedded equity tables, a jam and call model in ICM points, per-seat reads),
# built it against the elite brief and kit; frozen at md5 5f92fb3b1b7519f06b79234d41cfa5ba and copied here unchanged apart from this header.
# The archive is docs/drills/field/out_o11_bot.py. Played through hyperion.sim.bestiary (registry name
# `out_o11`): a held-out judge, never tuned on, never in a night pool. Do not edit; a new bot is a new file.
#
"""rival_bot — 8-max SNG no-limit hold'em bot. Standard library only, <1 ms per decision.

Strategy summary (see NOTEBOOK.md):
  * Preflop: precomputed 169-class equities; position-based open/3-bet ranges when deep; an
    explicit jam/call-jam EV model (fold equity x calling ranges x precomputed equity vs top-X%
    ranges) converted to tournament points with a truncated-Harville ICM when stacks are short.
  * Postflop: fast 7-card evaluator + feature-bucketed equity table (made hand / draws / board
    texture -> equity vs 1 and 2 random hands, precomputed offline), pot-odds and value-betting
    logic, ICM risk premium on stack-committing decisions.
  * Per-seat opponent model from obs.history (vpip, aggression, fold-to-bet, erratic sizing).
  * Deterministic: RNG seeded from new_table inputs; wall clock read only as a time guard.
"""
import time
import random

try:
    from kit import Agent
except Exception:  # pragma: no cover
    class Agent(object):
        def new_table(self, rules, seat, n_players): pass
        def act(self, obs): raise NotImplementedError
        def hand_end(self, result): pass

# ----------------------------------------------------------------------------------------------
# Hand evaluator (5..7 cards). score = (category << 20) | value
# ----------------------------------------------------------------------------------------------
_N = 1 << 13
STRAIGHT = [-1] * _N
TOP1 = [0] * _N
TOP2 = [0] * _N
TOP3 = [0] * _N
TOP5 = [0] * _N
POP = [0] * _N
for _m in range(1, _N):
    _r = [i for i in range(12, -1, -1) if _m >> i & 1]
    POP[_m] = len(_r)
    TOP1[_m] = _r[0]
    _v = 0
    for i in range(2): _v = _v * 13 + (_r[i] if i < len(_r) else 0)
    TOP2[_m] = _v
    _v = 0
    for i in range(3): _v = _v * 13 + (_r[i] if i < len(_r) else 0)
    TOP3[_m] = _v
    _v = 0
    for i in range(5): _v = _v * 13 + (_r[i] if i < len(_r) else 0)
    TOP5[_m] = _v
    for top in range(12, 3, -1):
        if (_m >> (top - 4)) & 31 == 31:
            STRAIGHT[_m] = top
            break
    else:
        if _m & 0x100F == 0x100F:
            STRAIGHT[_m] = 3
_P13_3 = 13 ** 3
_P13_2 = 169


def evaluate(cards):
    s0 = s1 = s2 = s3 = 0
    m = 0
    rc = [0] * 13
    for c in cards:
        r = c >> 2
        rc[r] += 1
        m |= 1 << r
        s = c & 3
        if s == 0: s0 |= 1 << r
        elif s == 1: s1 |= 1 << r
        elif s == 2: s2 |= 1 << r
        else: s3 |= 1 << r
    for fm in (s0, s1, s2, s3):
        if fm and POP[fm] >= 5:
            st = STRAIGHT[fm]
            if st >= 0:
                return (8 << 20) | st
            return (5 << 20) | TOP5[fm]
    quad = trip = -1
    p1 = p2 = -1
    trip2 = -1
    for r in range(12, -1, -1):
        n = rc[r]
        if n == 2:
            if p1 < 0: p1 = r
            elif p2 < 0: p2 = r
        elif n == 3:
            if trip < 0: trip = r
            elif trip2 < 0: trip2 = r
        elif n == 4:
            if quad < 0: quad = r
    if quad >= 0:
        return (7 << 20) | (quad * 13 + TOP1[m & ~(1 << quad)])
    if trip >= 0 and (p1 >= 0 or trip2 >= 0):
        low = p1 if trip2 < 0 else max(p1, trip2)
        return (6 << 20) | (trip * 13 + low)
    st = STRAIGHT[m]
    if st >= 0:
        return (4 << 20) | st
    if trip >= 0:
        return (3 << 20) | (trip * _P13_2 + TOP2[m & ~(1 << trip)])
    if p2 >= 0:
        return (2 << 20) | (p1 * _P13_2 + p2 * 13 + TOP1[m & ~((1 << p1) | (1 << p2))])
    if p1 >= 0:
        return (1 << 20) | (p1 * _P13_3 + TOP3[m & ~(1 << p1)])
    return TOP5[m]


# ----------------------------------------------------------------------------------------------
# Preflop hand classes: index 0..168. pairs r*13+r; suited hi*13+lo (hi>lo); offsuit lo*13+hi.
# ----------------------------------------------------------------------------------------------
def hand_class(hole):
    a, b = hole
    ra, rb = a >> 2, b >> 2
    if ra == rb:
        return ra * 13 + ra
    if ra < rb: ra, rb = rb, ra
    if (a & 3) == (b & 3):
        return ra * 13 + rb
    return rb * 13 + ra


def class_combos(idx):
    hi, lo = divmod(idx, 13)
    if hi == lo: return 6
    if hi > lo: return 4
    return 12


# ----------------------------------------------------------------------------------------------
# Postflop feature key (shared with precompute.py). Returns a tuple of small ints.
#   (street, cat, sub, kick, fd, sd, bsuit, bstr, bpair)
# ----------------------------------------------------------------------------------------------
def pf_key(hole, board):
    nb = len(board)
    st = nb - 2
    h0, h1 = hole
    r0, r1 = h0 >> 2, h1 >> 2
    bmask = 0
    bsc = [0, 0, 0, 0]
    brc = [0] * 13
    for c in board:
        r = c >> 2
        bmask |= 1 << r
        brc[r] += 1
        bsc[c & 3] += 1
    bmax = TOP1[bmask]
    bpair = max(brc)              # 1 none, 2 paired, 3 trips, 4 quads
    bsuit = max(bsc)              # max suit count on board
    full = list(hole) + list(board)
    sc = evaluate(full)
    cat = sc >> 20
    bsc_only = evaluate(board)
    bcat = bsc_only >> 20
    sub = 0; kick = 0; fd = 0; sd = 0
    pocket = (r0 == r1)
    # texture buckets
    bs = 0 if bsuit <= 2 else (1 if bsuit == 3 else 2)
    bstr = 0
    for r in range(0, 9):
        if POP[(bmask >> r) & 31] >= 3:
            bstr = 1; break
    if bstr == 0 and POP[bmask & 0x100F] >= 3: bstr = 1
    bp = 0 if bpair == 1 else (1 if bpair == 2 else 2)
    if cat == 0:
        kick = (1 if r0 > bmax else 0) + (1 if r1 > bmax else 0)
    elif cat == 1:
        if pocket:
            above = POP[bmask >> (r0 + 1)] if r0 < 12 else 0
            sub = min(above, 2)             # 0 overpair, 1 one over, 2 two+ over
        elif bpair >= 2 and brc[r0] == 0 and brc[r1] == 0:
            sub = 6                          # board pair only, we have nothing
            kick = (1 if r0 > bmax else 0) + (1 if r1 > bmax else 0)
        else:
            pr, other = (r0, r1) if brc[r0] else (r1, r0)
            above = POP[bmask >> (pr + 1)] if pr < 12 else 0
            sub = 3 + min(above, 2)          # 3 top pair, 4 second, 5 lower
            kick = 2 if other > bmax else (1 if other >= 8 else 0)
    elif cat == 2:
        if pocket and bpair >= 2:
            sub = 1 if r0 > TOP1[_pairmask(brc)] else 2
        elif brc[r0] and brc[r1] and not pocket:
            sub = 3 if (r0 == bmax or r1 == bmax) else 4
        elif (brc[r0] or brc[r1]) and bpair >= 2:
            pr = r0 if brc[r0] else r1
            sub = 5 if pr > TOP1[_pairmask(brc)] else 6
            kick = 1 if pr == bmax else 0
        else:
            sub = 0                          # board two pair, we play a kicker
            kick = (1 if r0 > bmax else 0) + (1 if r1 > bmax else 0)
    elif cat == 3:
        if pocket and brc[r0]:
            sub = 1                          # set
            kick = 1 if r0 == bmax else 0
        elif bpair >= 3:
            sub = 0                          # board trips
            kick = (1 if r0 > bmax else 0) + (1 if r1 > bmax else 0)
        else:
            sub = 2                          # trips with one hole card
            other = r1 if brc[r0] >= 2 else r0
            kick = 2 if other > bmax else (1 if other >= 8 else 0)
    elif cat == 4:
        if bcat == 4:
            sub = 0
            kick = 1 if (sc & 0xFFFFF) > (bsc_only & 0xFFFFF) else 0
        else:
            one = (evaluate([h0] + list(board)) >> 20 == 4) or (evaluate([h1] + list(board)) >> 20 == 4)
            sub = 1 if one else 2
            kick = 1 if (sc & 0xFFFFF) == 12 else 0   # broadway straight
    elif cat == 5:
        if bcat == 5:
            sub = 0
            kick = 1 if (sc & 0xFFFFF) > (bsc_only & 0xFFFFF) else 0
        else:
            fs = -1
            for s in range(4):
                if bsc[s] >= 3: fs = s
            in0 = (h0 & 3) == fs; in1 = (h1 & 3) == fs
            if in0 and in1:
                sub = 4
                hr = max(r0, r1)
            else:
                hr = r0 if in0 else r1
                sub = 1 if hr < 10 else (2 if hr < 12 else 3)
            kick = 1 if hr == 12 else 0
    else:
        sub = 0 if bcat >= cat else (1 if pocket else 2)
        if cat == 6 and bcat < 6:
            # full house: trips from pocket set (strong) vs board trips + our pair etc.
            sub = 1 if (pocket and brc[r0]) else 2
    if st < 3 and cat < 4:
        # flush draw
        hs0, hs1 = h0 & 3, h1 & 3
        for s in range(4):
            cnt = bsc[s] + (hs0 == s) + (hs1 == s)
            if cnt == 4 and (hs0 == s or hs1 == s):
                fd = 2 if (hs0 == s and hs1 == s) else 1
        # straight draw: ranks completing a straight (that the board alone would not complete)
        m = bmask | (1 << r0) | (1 << r1)
        outs = 0
        for r in range(13):
            if not (m >> r) & 1:
                if STRAIGHT[m | (1 << r)] >= 0 and STRAIGHT[bmask | (1 << r)] < 0:
                    outs += 1
        sd = 0 if outs == 0 else (1 if outs == 1 else 2)
    return (st, cat, sub, kick, fd, sd, bs, bstr, bp)


def _pairmask(brc):
    m = 0
    for r in range(13):
        if brc[r] >= 2: m |= 1 << r
    return m


def pack_key(k):
    v = 0
    for x in k:
        v = v * 10 + x
    return v


