# Preflop playability percentile per class: 0.0 = best hand, 1.0 = worst.
PRE_RANK = [0.5] * 169
if EQ_RANDOM is not None:
    _score = [0.55 * EQ_RANDOM[0][i] + 0.45 * EQ_RANDOM[3][i] for i in range(169)]
    _order = sorted(range(169), key=lambda i: -_score[i])
    _c = 0
    for _i in _order:
        PRE_RANK[_i] = _c / 1326.0
        _c += class_combos(_i)
else:  # pragma: no cover - tables missing: crude fallback
    for _i in range(169):
        _hi, _lo = divmod(_i, 13)
        PRE_RANK[_i] = 1.0 - (max(_hi, _lo) * 2 + min(_hi, _lo) + (13 if _hi == _lo else 0) + (2 if _hi > _lo else 0)) / 54.0


